-- 研究池新增：可控核聚变产业链 8 环节 / 65 家（2026-10-28）
-- 上市 41 家、未上市 24 家
-- 归属修正：旌晟超导 quantum→fusion；西部超导/抚顺特钢/应流股份/雷电微力 归回 aerospace；
--           中天科技 归回 quantum；中科富海/冰轮环境 归回 quantum
ON CONFLICT (name) DO UPDATE SET
  code=EXCLUDED.code, industry=EXCLUDED.industry, seg=EXCLUDED.seg,
  listed=EXCLUDED.listed, round=EXCLUDED.round, valuation=EXCLUDED.valuation,
  rev=EXCLUDED.rev, data=EXCLUDED.data, updated_at=now();

-- 按主营归属修正（跨行业只保留一处）
UPDATE public.research_companies SET industry='aerospace', seg='aero-material', updated_at=now()
 WHERE name IN ('西部超导','抚顺特钢');
UPDATE public.research_companies SET industry='aerospace', seg='aero-engine', updated_at=now()
 WHERE name='应流股份';
UPDATE public.research_companies SET industry='aerospace', seg='space-payload', updated_at=now()
 WHERE name='雷电微力';
UPDATE public.research_companies SET industry='quantum', seg='q-communication', updated_at=now()
 WHERE name='中天科技';
UPDATE public.research_companies SET industry='quantum', seg='q-cryo', updated_at=now()
 WHERE name IN ('中科富海','冰轮环境');
